#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <errno.h>

static long long abs_ll(long long x) {
    if (x == LLONG_MIN) {
        // Negating would overflow
        puts("OVERFLOW");
        exit(0);
    }
    return x < 0 ? -x : x;
}

static long long gcd_ll(long long a, long long b) {
    while (b != 0) {
        long long r = a % b;
        a = b;
        b = r;
    }
    return a;
}

int main(int argc, char **argv) {
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    char *end;
    errno = 0;
    long long v1 = strtoll(argv[1], &end, 10);
    if (end == argv[1] || *end != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    errno = 0;
    long long v2 = strtoll(argv[2], &end, 10);
    if (end == argv[2] || *end != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    // Take absolute values, handling LLONG_MIN overflow
    long long a = abs_ll(v1);
    long long b = abs_ll(v2);

    // Range check (both numbers must be <= 1,000,000)
    if (a > 1000000LL || b > 1000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    // Compute GCD
    long long g = gcd_ll(a, b);
    if (g == 0) {
        puts("gcd=0 lcm=0");
        return 0;
    }

    // Compute LCM safely (a/g * b fits in 64-bit because inputs are limited)
    long long lcm = (a / g) * b;
    printf("gcd=%ld lcm=%ld\n", g, lcm);
    return 0;
}
